import React from 'react'
import { IMG_CDN } from '../Utils/constants'

const MovieCard = ({posterPath}) => {
  return (
    <div className='w-48'>
      <img src={IMG_CDN+posterPath} alt='movie-card'/>
    </div>
  )
}

export default MovieCard
